import {aggregateMaterials,materialTotal,selectedMaterialHistory} from './aggregation.js';

import {receiptSummary,addReceipt,cancelReceipt} from './receipts.js';
import './style.css';
import './readability.css';
import './aggregation.css';
import {sortRequests,requestSortFields} from './sort.js';
import {Store,config,idb} from './store.js';
import {esc as e,uuid,number,label,clean,filterRequests,matchesSearch,approvalStatus,validateRecord,fingerprint,sha256} from './core.js';
import {readWorkbook,detectSheet,extractRows,columnName,exportRequests,exportMaterialTotals} from './excel.js';
import {download,buildBackup,readBackup,applyBackup} from './backup.js';
import {applyContactUpdate} from './contact-update.js';
import {contactList,withContactRows,phoneValue} from './contacts.js';
import {applyLocalUpdate} from './local-update.js';

const icons={box:'<path d="m12 3 9 5v8l-9 5-9-5V8z"/><path d="m3 8 9 5 9-5M12 13v8M7.5 5.5l9 5"/>',list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/>',phone:'<path d="M22 16.9v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.1 4.2 2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7c.1 1 .4 2 .7 2.9a2 2 0 0 1-.5 2.1L8 10a16 16 0 0 0 6 6l1.3-1.3a2 2 0 0 1 2.1-.5c.9.3 1.9.6 2.9.7a2 2 0 0 1 1.7 2z"/>',check:'<path d="m9 11 3 3 8-9"/><path d="M20 12v8H4V4h12"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',arrow:'<path d="m9 5 7 7-7 7"/>',edit:'<path d="m16 3 5 5-12 12H4v-5zM14 5l5 5"/>',history:'<path d="M3 10a9 9 0 1 1 1 8M3 4v6h6M12 7v5l3 2"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',cloud:'<path d="M6 18a5 5 0 1 1 1-9 6 6 0 0 1 11-1 5 5 0 0 1 0 10z"/>',logout:'<path d="M9 21H3V3h6M13 8l5 4-5 4m-5-4h10"/>',file:'<path d="M14 2H4v20h16V8zM14 2v6h6M8 13h8M8 17h8"/>'};
const icon=(name)=>`<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.box}</svg>`;
const store=new Store();let view='request',page=1,settingsTab='vendors',loading=false,upload=null,editing=null,restorePreview=null;
const aggregateSelection=new Set();
let aggregateFilter={q:'',trade:'',start:'',end:'',sort:'name'};
let filters={q:'',trade:'',start:'',end:'',vendor:'',applicant:'',location:'',review:false};let masterSearch='',masterTrade='';let mobileSummaryOpen=false;
let requestSort={key:'date',direction:'desc'};try{const saved=JSON.parse(localStorage.getItem('mm-request-sort'));if(saved&&requestSortFields.some(([k])=>k===saved.key)&&['asc','desc'].includes(saved.direction))requestSort=saved;}catch{}
function setRequestSort(key,direction){requestSort={key,direction};localStorage.setItem('mm-request-sort',JSON.stringify(requestSort));page=1;render();}
function sortedRequests(){return sortRequests(filterRequests(store.records,filters,store.records),requestSort,store.records);}
function sortHeading(key,text){return `<th aria-sort="${requestSort.key===key?(requestSort.direction==='asc'?'ascending':'descending'):'none'}"><button type="button" data-action="sort-column" data-key="${key}" class="sort-heading ${requestSort.key===key?'selected':''}">${text}<span aria-hidden="true">${requestSort.key===key?(requestSort.direction==='asc'?'↑':'↓'):'↕'}</span></button></th>`;}
const active=kind=>store.records.filter(r=>r.kind===kind&&!r.deleted);
const vendorName=id=>store.records.find(r=>r.id===id&&r.kind==='vendor')?.data.name||'';
const stamp=v=>v?new Date(v).toLocaleString('ko-KR'):'';
const btn=(text,action,style='primary',attrs='')=>`<button type="button" class="btn ${style}" data-action="${action}" ${attrs}>${text}</button>`;
const badge=(text,type='')=>`<span class="badge ${type}">${e(text)}</span>`;
const empty=(text='검색 결과가 없습니다.')=>`<div class="empty">${icon('search')}<h3>${e(text)}</h3><p>검색조건을 바꾸거나 새 항목을 등록해 보세요.</p></div>`;
const canEdit=()=>store.role!=='viewer';
const option=(value,text,selected)=>`<option value="${e(value)}" ${String(value)===String(selected)?'selected':''}>${e(text)}</option>`;
const vendorSelect=(name,value,role='',allowEmpty=true)=>`<select name="${name}">${allowEmpty?option('','미등록 / 연결 안 함',value):''}${active('vendor').filter(r=>!role||r.data.roles?.includes(role)).sort((a,b)=>a.data.name.localeCompare(b.data.name,'ko')).map(r=>option(r.id,r.data.name,value)).join('')}</select>`;
function toast(msg,error=false){document.querySelector('#toast')?.remove();const t=document.createElement('div');t.id='toast';t.className='toast '+(error?'error':'');t.setAttribute('role','status');t.textContent=msg;document.body.append(t);setTimeout(()=>t.remove(),6500);}
async function run(fn){if(loading)return;loading=true;document.body.classList.add('busy');try{await fn();}catch(err){console.error(err);toast(err.message||'작업 중 오류가 발생했습니다.',true);}finally{loading=false;document.body.classList.remove('busy');}}
function title(text,sub,actions=''){return `<div class="page-title"><div><div class="eyebrow">MATERIAL MANAGEMENT</div><h1>${text}</h1><p>${sub}</p></div><div class="title-actions">${actions}</div></div>`;}
function shell(body){
 const nav=[['request','list','청구내역 조회'],['vendor','phone','업체연락처 조회'],['approval','check','자재승인목록 조회'],['aggregate','box','자재별 집계'],['settings','settings','설정']];
 const local=store.mode==='local';
 document.querySelector('#app').innerHTML=`<aside class="sidebar"><a href="#" class="brand" data-view="request"><span class="brand-icon">${icon('box')}</span><span>자재청구 관리<small>MATERIAL DESK</small></span></a><div class="project"><span class="project-dot"></span><div>${e(store.projectName)}<small>기계 · 소방 통합 관리</small></div></div><div class="nav-label">현장 관리</div><nav>${nav.map(([v,i,n])=>`<button class="nav-item ${view===v?'active':''}" data-view="${v}">${icon(i)}<span>${n}</span>${view===v?'<span class="nav-dot"></span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div>${icon(local?'file':'cloud')} <b>${local?'로컬 확인 모드':'Supabase 연결'}</b></div><p>${local?'이 브라우저에 저장됩니다.<br>공유 저장은 설정에서 연결하세요.':e(store.session?.user?.email||'로그인 필요')}</p><button class="side-link" data-action="connection">${local?'공유 데이터 연결하기 →':'연결 및 사용자 설정 →'}</button></div></aside><div class="workspace"><header class="topbar"><div><span class="breadcrumb">현장 관리</span><span class="slash">/</span><b>${view==='upload'?'청구서 업로드':nav.find(n=>n[0]===view)?.[2]||'자재 관리'}</b></div><div class="top-right"><span class="status-dot ${local?'local':''}"></span><span>${local?'로컬 저장':store.session?'공유 저장':'로그인 필요'}</span><span class="avatar">${local?'현':store.role==='admin'?'관':'사'}</span></div></header><main>${store.mode==='cloud'&&!store.session?loginScreen():store.mode==='cloud'&&!store.projectId?projectScreen():body}</main><footer>파주 콘텐츠시티 · 자재청구 관리<span>기계 / 소방</span></footer></div><div id="modal-root"></div>`;
}
function arrangeRequestDates(){const range=document.querySelector('.desktop-date-range'),slot=document.querySelector('.mobile-date-slot'),main=document.querySelector('#request-filter .filter-main');if(!range||!slot||!main)return;if(matchMedia('(max-width:767px)').matches)slot.append(range);else main.insertBefore(range,main.querySelector('button'));}
function render(){
 if(store.mode==='cloud'&&!store.session){shell('');return;}
 const fn={request:requestsView,vendor:vendorsView,approval:approvalsView,settings:settingsView,aggregate:aggregateView,upload:uploadView};shell(fn[view]());arrangeRequestDates();
}
function loginScreen(){return `<div class="login-wrap"><div class="login-illustration">${icon('box')}<h1>현장의 모든 자재,<br>한 곳에서 관리하세요.</h1><p>기계·소방 청구내역과 거래처 정보를<br>PC와 휴대폰에서 함께 확인합니다.</p></div><div class="panel login-panel"><div class="eyebrow">WELCOME BACK</div><h2>공유 데이터 로그인</h2><p>Supabase에 등록된 이메일 계정으로 로그인하세요.</p><form id="login-form"><label>이메일<input type="email" name="email" autocomplete="username" required placeholder="이메일 주소"></label><label>비밀번호<input type="password" name="password" autocomplete="current-password" required minlength="6" placeholder="비밀번호"></label><button class="btn primary full" type="submit">로그인 ${icon('arrow')}</button></form><div class="notice">처음 연결할 때는 Supabase SQL Editor에서 전용 테이블 생성 SQL을 실행하고, Authentication에서 사용자를 등록해야 합니다.</div>${btn('연결 설정 확인','connection','ghost')}${import.meta.env.DEV?btn('로컬 확인 모드로 사용','local-mode','ghost'):''}</div></div>`;}
function projectScreen(){return `<div class="panel narrow"><h1>새 현장 시작하기</h1><p>이 계정에 연결된 자재 관리 현장이 없습니다.</p><form id="project-form"><label>현장명<input name="name" value="파주 콘텐츠시티" required></label><button type="submit" class="btn primary">현장 만들기</button></form><p class="help">기존 현장에 참여하려면 현장 관리자에게 사용자 권한 등록을 요청하세요.</p></div>`;}
function requestsView(){
 const all=active('request'),rows=sortedRequests(),pages=Math.max(1,Math.ceil(rows.length/25));page=Math.min(page,pages);const slice=rows.slice((page-1)*25,page*25);
 const last=all.map(r=>r.data.date).sort().at(-1);
 const summary=[['누적 청구 항목',number(all.length),'전체 내역','list',''],['기계 청구',number(all.filter(r=>r.data.trade==='기계').length),'기계설비 공사','box','blue'],['소방 청구',number(all.filter(r=>r.data.trade==='소방').length),'소방설비 공사','check','orange'],['최근 청구일',last?last.slice(5).replace('-','.'):'—',last?last.slice(0,4)+'년 기준':'등록된 내역 없음','history','']];
 const summaryActions=canEdit()?btn(icon('plus')+' 직접 등록','new-request','secondary')+btn(icon('upload')+' 청구서 업로드','upload'):'';
 return title('청구내역 조회','필요한 자재 내역을 찾고, 새로운 청구서를 한 번에 정리하세요.')+`<details class="request-summary" ${!matchMedia('(max-width:767px)').matches||mobileSummaryOpen?'open':''}><summary><span class="summary-closed">요약·등록 펼치기</span><span class="summary-open">요약·등록 접기</span><small>전체 ${number(all.length)}건</small><span class="summary-chevron">⌄</span></summary><div class="summary-actions">${summaryActions}</div><div class="stats">${summary.map(([a,b,c,i,k])=>`<div class="stat ${k}"><div><span>${a}</span><span class="stat-icon">${icon(i)}</span></div><strong>${b}</strong><small>${c}</small></div>`).join('')}</div></details><section class="panel filter-panel"><div class="segmented">${[['','전체'],['기계','기계'],['소방','소방']].map(([v,n])=>`<button class="${filters.trade===v?'selected':''}" data-action="trade" data-value="${v}">${n}</button>`).join('')}</div><form id="request-filter"><div class="filter-main"><div class="searchbox">${icon('search')}<input name="q" placeholder="품명, 규격, 업체, 작업위치 검색" value="${e(filters.q)}" aria-label="청구내역 검색"></div><div class="desktop-date-range"><input type="date" name="start" value="${e(filters.start)}" aria-label="시작 날짜"><span class="date-dash">~</span><input type="date" name="end" value="${e(filters.end)}" aria-label="종료 날짜"></div><button type="submit" class="btn primary">조회</button>${btn('초기화','reset-filter','ghost')}</div><details class="filter-more"><summary>상세 검색 <span>업체 · 신청자 · 작업위치 · 확인 항목</span></summary><div class="filter-extra"><div class="mobile-date-slot"></div><label>업체${vendorSelect('vendor',filters.vendor)}</label><label>신청자<input name="applicant" value="${e(filters.applicant)}" placeholder="신청자 검색"></label><label>작업위치<input name="location" value="${e(filters.location)}" placeholder="작업위치 검색"></label><label class="check-label"><input type="checkbox" name="review" ${filters.review?'checked':''}> 확인 필요한 내역</label></div></details></form></section><div class="section-heading"><div><h2>청구내역 <span class="count">${number(rows.length)}</span></h2><p>${requestSortFields.find(([k])=>k===requestSort.key)?.[1]} ${requestSort.direction==='asc'?'오름차순':'내림차순'} · 항목을 선택하면 상세정보를 확인할 수 있습니다.</p></div>${btn(icon('download')+' 엑셀 내려받기','export','secondary')}</div><div class="sort-controls"><label for="request-sort-key">정렬 기준</label><select id="request-sort-key" aria-label="청구내역 정렬 기준">${requestSortFields.map(([k,n])=>option(k,n,requestSort.key)).join('')}</select><button type="button" data-action="sort-direction" class="btn secondary" aria-label="정렬 방향 변경">${requestSort.direction==='asc'?'↑ 오름차순':'↓ 내림차순'}</button><span>빈 값은 마지막에 표시합니다.</span></div>${rows.length?`<div class="table-panel"><table class="request-table"><thead><tr>${[['trade','분류'],['date','날짜'],['name','품명 / 규격'],['unit','단위'],['quantity','수량'],['manufacturerId','원자재'],['dealerId','대리점'],['location','작업위치'],['applicant','신청자'],['note','비고']].map(([key,text])=>sortHeading(key,text)).join('')}<th></th></tr></thead><tbody>${slice.map(r=>{const d=r.data;return `<tr data-action="detail" data-id="${r.id}" tabindex="0" role="button" aria-label="${e(d.name)} 상세"><td class="cell-trade">${badge(d.trade,d.trade==='소방'?'fire':'mechanical')}</td><td class="cell-date">${e(d.date)}</td><td class="cell-name"><b>${e(d.name)}</b><span class="receipt-status ${receiptSummary(d).status==='입고완료'?'complete':''}">${receiptSummary(d).status}</span><small>${e(d.spec||'규격 미등록')}<span class="mobile-only compact-location" title="${e(d.location||'')}"> · ${e(d.location||'작업위치 미등록')}</span></small></td><td class="cell-unit">${e(d.unit||'—')}</td><td class="cell-quantity">${number(d.quantity)}<span class="mobile-only"> ${e(d.unit)}</span></td><td class="cell-manufacturer" data-label="원자재">${e(vendorName(d.manufacturerId)||d.rawManufacturer||'미등록')}</td><td class="cell-dealer" data-label="대리점">${e(vendorName(d.dealerId)||d.rawDealer||'미등록')}</td><td class="cell-location" data-label="작업위치">${e(d.location||'—')}</td><td class="cell-applicant">${e(d.applicant||'—')}</td><td class="cell-note" title="${e(d.note)}">${e(d.note||'—')}</td><td class="cell-arrow">${icon('arrow')}</td></tr>`;}).join('')}</tbody></table></div><div class="pagination"><span>${number(rows.length)}건 중 ${number((page-1)*25+1)}–${number(Math.min(page*25,rows.length))}건</span><div>${btn('이전','prev','secondary',page<=1?'disabled':'')}<b>${page} <span>/ ${pages}</span></b>${btn('다음','next','secondary',page>=pages?'disabled':'')}</div></div>`:empty()}<div class="info-line">${icon('check')} 단위가 다른 수량은 합산하지 않습니다. 원본과 사용자 수정 이력을 함께 보관합니다.</div>`;
}
function masterFilter(placeholder){return `<form id="master-filter" class="panel master-filter"><div class="segmented">${[['','전체'],['기계','기계'],['소방','소방']].map(([v,n])=>`<button type="button" data-action="master-trade" data-value="${v}" class="${masterTrade===v?'selected':''}">${n}</button>`).join('')}</div><div class="searchbox">${icon('search')}<input name="q" placeholder="${placeholder}" value="${e(masterSearch)}"></div><button class="btn primary">검색</button></form>`;}
function vendorsView(){
 const all=contactList(store.records),rows=all.filter(c=>(!masterTrade||c.trade===masterTrade)&&(!masterSearch||matchesSearch([c.item,c.manufacturer,c.dealer,c.phone,c.fax,c.person,c.note,...(c.emails||[])].join(' '),masterSearch))).sort((a,b)=>a.trade.localeCompare(b.trade,'ko')||(a.source?.row||9999)-(b.source?.row||9999));
 return title('업체연락처 조회','품목별 제조사·대리점과 해당 대리점의 연락처를 함께 확인하세요.',canEdit()?btn(icon('plus')+' 연락처 등록','contact-new')+btn('업체 등록','new-vendor','secondary'):'')+masterFilter('품목, 제조사, 대리점, 전화, 담당자 검색')+`<div class="section-heading"><div><h2>품목별 연락처 <span class="count">${rows.length}</span></h2><p>기계 ${all.filter(c=>c.trade==='기계').length}행 · 소방 ${all.filter(c=>c.trade==='소방').length}행 · 전화·팩스는 해당 행의 대리점 정보입니다.</p></div>${btn('확인 필요 자료','contact-pending','secondary')}</div><p class="mobile-only contact-scroll-hint">항목을 누르면 품목과 전체 연락처를 확인할 수 있습니다.</p>${rows.length?`<div class="table-panel"><table class="contact-table"><thead><tr><th>공종</th><th>품목</th><th>제조사</th><th>대리점</th><th>연락처</th><th>팩스</th><th>담당자·비고</th><th></th></tr></thead><tbody>${rows.map(c=>`<tr data-action="contact-detail" data-id="${c.ownerId}" data-contact="${c.id}" role="button" tabindex="0" aria-label="${e(c.manufacturer)} ${e(c.dealer)} 연락처 상세"><td>${badge(c.trade,c.trade==='소방'?'fire':'mechanical')}</td><td class="contact-item"><b>${e(c.item)}</b></td><td>${e(c.manufacturer)}</td><td><b>${e(c.dealer)}</b></td><td class="contact-phone">${e(c.phone||'미등록')}</td><td class="contact-phone">${e(c.fax||'—')}</td><td class="contact-note">${e(c.person||'')}${c.person&&c.note?'<br>':''}${e(c.note||'—')}${c.emails?.length?`<small>${e(c.emails.join(' / '))}</small>`:''}</td><td>${icon('arrow')}</td></tr>`).join('')}</tbody></table></div>`:empty('등록된 연락처가 없습니다.')}`;
}
function approvalsView(){const rows=active('approval').filter(r=>(!masterTrade||r.data.trade===masterTrade)&&(!masterSearch||matchesSearch([r.data.name,...r.data.options.map(o=>vendorName(o.vendorId)||o.name)].join(' '),masterSearch)));
 return title('자재승인목록 조회','공종별 승인 품목과 제조사 후보를 확인하고 관리하세요.',canEdit()?btn(icon('plus')+' 승인 품목 등록','new-approval'):'')+masterFilter('승인 품목 또는 제조사 검색')+`<div class="approval-banner">${icon('check')}<div><b>기계 ${active('approval').filter(r=>r.data.trade==='기계').length}개 · 소방 ${active('approval').filter(r=>r.data.trade==='소방').length}개 품목</b><span>A·B·C·D는 원본 후보 구분입니다. 우선순위나 승인 등급을 뜻하지 않습니다.</span></div></div><div class="table-panel"><table class="approval-table"><thead><tr><th>공종</th><th>승인 품목</th><th>제조사 A</th><th>제조사 B</th><th>제조사 C</th><th>제조사 D</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr data-action="detail" data-id="${r.id}" role="button" tabindex="0"><td>${badge(r.data.trade,r.data.trade==='소방'?'fire':'mechanical')}</td><td><b>${e(r.data.name)}</b><small class="revision">v${r.data.revision||1}</small></td>${['A','B','C','D'].map(slot=>{const o=r.data.options.find(o=>o.slot===slot);return `<td data-label="제조사 ${slot}">${e(o?(vendorName(o.vendorId)||o.name):'—')}</td>`;}).join('')}<td>${icon('arrow')}</td></tr>`).join('')}</tbody></table></div>${rows.length?'':empty()}`;
}
function settingsView(){const tabs=[['vendors','업체·이메일'],['aliases','업체명 별칭'],['backup','백업·복원'],['history','변경 이력'],['imports','가져오기 이력'],['connection','연결·사용자']];
 const body={vendors:()=>`<div class="panel"><h2>품목별 업체연락처 관리</h2><p>연락처 조회 화면에서 업체를 선택해 품목별 전화·팩스·이메일·담당자를 수정할 수 있습니다.</p>${btn(icon('phone')+' 업체연락처 열기','go-vendor','secondary')} ${canEdit()?btn(icon('plus')+' 업체 등록','new-vendor'):''}</div><div class="panel"><h2>자재승인목록 관리</h2><p>품목 오입력은 직접 정정하고 실제 승인 제조사 변경은 관리자가 처리합니다.</p>${btn('승인목록 열기','go-approval','secondary')} ${canEdit()?btn('승인 품목 등록','new-approval'):''}</div>`,aliases:aliasesSettings,backup:backupSettings,history:historySettings,imports:importsSettings,connection:connectionSettings};
 return title('설정','현장 정보를 관리하고, 데이터를 안전하게 보관하세요.')+`<div class="tabs">${tabs.map(([v,n])=>`<button data-action="settings-tab" data-value="${v}" class="${settingsTab===v?'active':''}">${n}</button>`).join('')}</div>${body[settingsTab]()}`;
}
function aliasesSettings(){return `<div class="section-heading"><div><h2>업체명 통일 규칙</h2><p>이후 업로드에 적용할 표기를 등록합니다. 기존 청구내역을 자동 변경하지 않습니다.</p></div>${canEdit()?btn(icon('plus')+' 별칭 추가','new-alias'):''}</div><div class="table-panel"><table><thead><tr><th>원본 표기</th><th>역할</th><th>연결 업체</th><th></th></tr></thead><tbody>${active('alias').map(r=>`<tr><td>${e(r.data.alias)}</td><td>${e(r.data.role)}</td><td>${e(vendorName(r.data.vendorId))}</td><td>${canEdit()?btn('수정','edit','ghost',`data-id="${r.id}"`):''}</td></tr>`).join('')}</tbody></table></div>`;}
function backupSettings(){return `<div class="settings-grid"><div class="panel"><div class="feature-icon">${icon('download')}</div><h2>전체 데이터 백업</h2><p>청구내역·업체·승인목록·별칭·이력과 원본 파일을 ZIP으로 보관합니다.</p><dl class="mini-stats"><div><dt>청구 항목</dt><dd>${number(active('request').length)}</dd></div><div><dt>원본·증빙 파일</dt><dd>${store.files.length}</dd></div></dl>${btn('전체 백업 다운로드','backup')}</div><div class="panel"><div class="feature-icon warm">${icon('history')}</div><h2>백업 복원</h2><p>백업을 검사하고 현재 데이터와 비교한 뒤 관리자 확인을 거쳐 교체합니다.</p><div class="notice">복원 전 현재 상태를 자동 백업합니다. 다른 현장의 백업도 가져올 수 있으므로 파일과 현장명을 확인하세요.</div>${store.role==='admin'?'<label class="btn secondary file-button">백업 ZIP 선택<input id="restore-file" type="file" accept=".zip" hidden></label>':'<p class="help">관리자만 복원할 수 있습니다.</p>'}${btn('복원 전 자동 백업 받기','pre-restore','ghost')}</div></div>`;}
function historySettings(){return `<div class="panel"><h2>최근 변경 이력</h2><p>수정 전후 값과 사유를 기록합니다.${store.mode==='cloud'?' 최근 500개 작업을 표시합니다.':''}</p>${historyTable(store.history.slice(0,100))}</div>`;}
function historyTable(items){return items.length?`<div class="audit-list">${items.map(h=>`<div class="audit-item"><span class="audit-symbol">${icon('history')}</span><div><b>${e(h.action||'수정')} · ${e(h.after?.data?.name||h.before?.data?.name||label[h.kind]||h.kind)}</b><p>${e(h.reason||'')}</p><small>${e(stamp(h.created_at))} · ${e(h.actor||h.actor_id||'사용자')}</small>${h.before?`<details><summary>변경 전후 비교</summary><div class="diff"><pre>${e(JSON.stringify(h.before?.data,null,2))}</pre><pre>${e(JSON.stringify(h.after?.data,null,2))}</pre></div></details>`:''}</div>${h.before&&canEdit()?btn('되돌리기','revert','ghost',`data-id="${h.id}"`):''}</div>`).join('')}</div>`:empty('아직 변경 이력이 없습니다.');}
function importsSettings(){return `<div class="panel"><h2>청구서 가져오기 이력</h2><p>보류 항목은 검토를 이어서 진행할 수 있습니다. 원본 파일도 내려받을 수 있습니다.</p>${active('batch').map(r=>`<div class="import-history"><div><b>${e(r.data.filename)}</b><p>${e(r.data.sheet)} · 반영 ${r.data.applied||0}행 / 보류 ${r.data.pending?.length||0}행</p><small>${e(stamp(r.data.at))}</small></div>${r.data.pending?.length&&canEdit()?btn('보류 검토','resume','secondary',`data-id="${r.id}"`):''}</div>`).join('')||'<p>등록된 업로드가 없습니다.</p>'}</div><div class="panel"><h2>보관 원본 파일</h2>${store.files.map(f=>`<div class="file-row">${icon('file')}<div><b>${e(f.name)}</b><small>${(f.size/1024).toFixed(1)} KB</small></div>${btn('다운로드','file-download','ghost',`data-id="${f.id}"`)}</div>`).join('')||'<p>보관된 파일이 없습니다.</p>'}</div>`;}
function connectionSettings(){const c=config();return `<div class="settings-grid"><div class="panel"><h2>Supabase 공유 저장 연결</h2><p>기존 사이트와 분리된 mm_ 전용 테이블과 mm-files 저장소를 사용합니다.</p><form id="connection-form"><label>프로젝트 URL<input name="url" type="url" value="${e(c.url||'https://dyakyuobvsiioxmiepoe.supabase.co')}" required placeholder="https://....supabase.co"></label><label>공개 키 (anon / publishable)<input name="key" type="password" value="${e(c.key)}" required autocomplete="off" placeholder="sb_publishable_..."></label><p class="help">service_role·secret 키는 입력하지 마세요. 공개 키에는 데이터베이스 권한 정책이 함께 필요합니다.</p><button class="btn primary" type="submit">연결 정보 저장</button></form><div class="notice">기존 테이블·정책·로그인 설정을 변경하지 않습니다. 새 전용 SQL 실행은 Supabase SQL Editor에서 한 번 필요합니다.</div>${btn('전용 SQL 다운로드','sql-download','secondary')}</div><div class="panel"><h2>사용자와 현장</h2><dl class="detail-grid"><dt>저장 방식</dt><dd>${store.mode==='local'?'로컬 브라우저 (IndexedDB)':'Supabase'}</dd><dt>현재 권한</dt><dd>${({admin:'관리자',editor:'편집자',viewer:'조회자'})[store.role]}</dd><dt>현재 현장</dt><dd>${e(store.projectName)}</dd></dl>${store.mode==='cloud'&&store.session?`${store.projects.length>1?`<label>현장 선택<select id="project-switch">${store.projects.map(p=>option(p.project_id,p.mm_projects.name,store.projectId)).join('')}</select></label>`:''}${btn('새로고침','refresh','secondary')}${store.role==='admin'?btn('로컬 자료를 공유 저장으로 가져오기','migrate-local','secondary'):''}${btn('로그아웃','logout','ghost')}<div class="notice">초기 자료를 공유 저장소로 옮기려면 로컬에서 전체 백업을 다운로드한 뒤 여기에서 로그인하여 백업을 복원하세요.</div>${store.role==='admin'?`<h3>사용자 권한 추가</h3><p class="help">Supabase Authentication에 먼저 등록한 사용자의 UUID를 입력하세요.</p><form id="member-form"><label>사용자 UUID<input name="user" required placeholder="사용자 ID"></label><label>권한<select name="role"><option value="viewer">조회자</option><option value="editor">편집자</option><option value="admin">관리자</option></select></label><button type="submit" class="btn secondary">현장 사용자 등록</button></form>`:''}`:btn('로그인 화면으로','cloud-mode','secondary')}${import.meta.env.DEV?btn('로컬 확인 모드로 전환','local-mode','ghost'):''}</div></div>`;}

function uploadView(){
 if(!canEdit())return empty('업로드 권한이 없습니다.');
 if(!upload)return title('청구서 업로드','본사 제출용 엑셀을 불러와 확인한 내역만 반영합니다.')+`<label class="upload-zone"><span class="upload-circle">${icon('upload')}</span><h2>자재청구서 엑셀을 선택하세요</h2><p>정리된 내역표 또는 본사 제출 청구서 · .xlsx · 최대 15MB</p><span class="btn primary">파일 선택</span><input id="excel-file" type="file" accept=".xlsx" hidden></label><div class="upload-guide"><div><b>01</b><h3>시트·수량 확인</h3><p>공종과 날짜, 실제 수량 열을 확인합니다.</p></div><div><b>02</b><h3>업체·중복 검토</h3><p>잘못 읽은 값은 저장 전에 수정합니다.</p></div><div><b>03</b><h3>선택 항목 반영</h3><p>확인한 행만 저장하고 원본을 보관합니다.</p></div></div>`;
 const u=upload,rows=u.rows||[],chosen=rows.filter(r=>r.selected),pending=rows.filter(r=>!r.selected);const mappingFields={name:'품명',spec:'규격',unit:'단위',quantity:'수량',note:'비고',trade:'공종',date:'날짜',manufacturer:'원자재',dealer:'대리점',location:'작업위치',applicant:'신청자'};
 return title('청구서 업로드 검토',`${e(u.filename)} · 원본을 보존하고 확인한 항목만 반영합니다.`,btn('다른 파일 선택','clear-upload','secondary'))+`<div class="steps"><span class="done">1 파일 선택</span><span class="current">2 시트 · 수량 확인</span><span>3 검토 · 반영</span></div>${u.wb?`<section class="panel"><form id="mapping-form"><div class="mapping-top"><label>시트 선택<select id="sheet-select">${u.wb.SheetNames.map(n=>option(n,n,u.sheet)).join('')}</select></label><label>공종<select name="trade">${option('','공종 선택',u.trade)}${option('기계','기계',u.trade)}${option('소방','소방',u.trade)}</select></label><label>청구일<input type="date" name="date" value="${e(u.date)}"></label><label>수량 열<select name="quantity">${Array.from({length:27},(_,i)=>option(i,`${columnName(i)}열`,u.map?.quantity)).join('')}</select></label></div>${u.info?.warnings.map(w=>`<div class="notice">${e(w)}</div>`).join('')||''}${!u.info?.supported?'<div class="notice">지원되는 품명·규격 머리글을 찾지 못했습니다. 다른 시트를 선택하세요.</div>':''}<details class="column-details"><summary>전체 열 연결 확인</summary><div class="column-grid">${Object.entries(mappingFields).filter(([k])=>k!=='quantity').map(([k,n])=>`<label>${n}<select name="col-${k}">${option(-1,'해당 열 없음',u.map?.[k])}${Array.from({length:27},(_,i)=>option(i,`${columnName(i)}열`,u.map?.[k])).join('')}</select></label>`).join('')}</div></details><div class="mapping-actions"><label class="check-label"><input type="checkbox" name="confirmed" ${u.confirmed?'checked':''} required> 원본을 확인했고 선택한 수량 열이 맞습니다.</label><button type="submit" class="btn secondary" ${!u.info?.supported?'disabled':''}>미리보기 갱신</button></div></form></section>`:'<div class="hint">이전에 보류한 내역을 이어서 검토합니다. 각 행을 수정한 뒤 선택하세요.</div>'}<div class="section-heading"><div><h2>변환 미리보기 <span class="count">${rows.length}</span></h2><p>선택 ${chosen.length}행 · 보류 ${pending.length}행 · 중복 후보 ${rows.filter(r=>r.duplicate).length}행</p></div><div>${btn('유효한 행 선택','select-valid','secondary')} ${btn('선택 해제','select-none','ghost')}</div></div><div class="table-panel"><table class="upload-table"><thead><tr><th>선택</th><th>공종·날짜</th><th>품명 / 규격</th><th>수량</th><th>원자재 / 대리점</th><th>확인사항</th><th></th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td><input type="checkbox" class="row-check" data-index="${i}" ${r.selected?'checked':''} aria-label="${e(r.data.name)} 선택"></td><td>${e(r.data.trade)}<small>${e(r.data.date)}</small></td><td><b>${e(r.data.name)}</b><small>${e(r.data.spec)}</small></td><td>${e(r.data.quantity)} ${e(r.data.unit)}</td><td>${e(vendorName(r.data.manufacturerId)||'미등록')}<small>${e(vendorName(r.data.dealerId)||'미등록')}</small></td><td>${r.duplicate?badge('중복 후보','warn'):''}${r.issues.map(v=>badge(v,'warn')).join(' ')||badge('확인 가능','good')}</td><td>${btn('수정','edit-upload','ghost',`data-index="${i}"`)}</td></tr>`).join('')}</tbody></table></div><div class="upload-footer"><div><b>${chosen.length}행 반영 예정</b><p>미선택 ${pending.length}행은 보류 이력으로 보관합니다. 선택한 중복 후보는 반복 청구로 별도 등록됩니다.</p></div>${btn(chosen.length?'확인한 '+chosen.length+'행 반영':'보류 내역 저장','commit-upload','primary',u.wb&&!u.confirmed?'disabled':'')}</div>`;
}

function showDialog(content,wide=false){document.querySelector('#modal-root').innerHTML=`<dialog class="modal ${wide?'wide':''}"><div class="modal-top"><span>자재청구 관리</span><button type="button" data-action="close-modal" class="icon-button" aria-label="닫기">${icon('close')}</button></div>${content}</dialog>`;const dialog=document.querySelector('dialog');dialog.showModal();dialog.addEventListener('cancel',event=>{event.preventDefault();closeModal();});}
function closeModal(force=false){const f=document.querySelector('#edit-form,#contact-form,#receipt-form');if(!force&&f?.dataset.dirty==='yes'&&!confirm('저장하지 않은 변경을 취소할까요?'))return;document.querySelector('dialog')?.close();document.querySelector('#modal-root').innerHTML='';editing=null;}
function detail(id){const r=store.records.find(r=>r.id===id);if(!r)return;const d=r.data,kind=r.kind;let body='';
 if(kind==='request'){const status=approvalStatus(d,store.records);body=`<div class="detail-badges">${badge(d.trade,d.trade==='소방'?'fire':'mechanical')}${badge(status[0],status[1])}${r.version>1?badge('사용자 수정','good'):''}</div><h2>${e(d.name)}</h2><p>${e(d.spec||'규격 미등록')} · ${e(d.date)}</p><dl class="detail-grid"><dt>수량</dt><dd><strong>${number(d.quantity)} ${e(d.unit)}</strong></dd><dt>원자재</dt><dd>${e(vendorName(d.manufacturerId)||d.rawManufacturer||'미등록')}</dd><dt>대리점</dt><dd>${e(vendorName(d.dealerId)||d.rawDealer||'미등록')}</dd><dt>작업위치</dt><dd>${e(d.location||'—')}</dd><dt>신청자</dt><dd>${e(d.applicant||'—')}</dd><dt>현재 비고</dt><dd>${e(d.note||'—')}</dd>${materialTotalMarkup(d)}</dl><div class="source"><b>원본 추적</b><p>${e(d.source?.file||'직접 등록')}<br>${e(d.source?.sheet||'')} ${d.source?.row?'· '+d.source.row+'행':''}</p><details><summary>원본 값 보기</summary><pre>${e(JSON.stringify(d.original||{},null,2))}</pre></details></div>`;
 body+=receiptPanel(r);
 const vendor=store.records.find(v=>v.id===d.dealerId);if(vendor?.data.phone)body+=`<a class="btn secondary" href="tel:${e(vendor.data.phone.replace(/[^+\d]/g,''))}">${icon('phone')} ${e(vendor.data.name)} 전화</a>`;
 }else if(kind==='vendor'){body=`<div class="detail-badges">${d.roles?.map(v=>badge(v,'good')).join(' ')}</div><h2>${e(d.name)}</h2><p>${e(d.trades?.join(' · '))}</p><dl class="detail-grid">${[['전화',d.phone],['휴대전화',d.mobile],['팩스',d.fax],['담당자',d.person],['이메일',d.email],['취급품목',d.items?.join(' · ')],['메모',d.note]].map(([k,v])=>`<dt>${k}</dt><dd>${e(v||'미등록')}</dd>`).join('')}</dl><div class="dialog-actions">${d.phone?`<a class="btn primary" href="tel:${e(d.phone.replace(/[^+\d]/g,''))}">${icon('phone')} 전화 연결</a>`:''}${d.email?`<a class="btn secondary" href="mailto:${e(d.email)}">메일 앱 열기</a>${btn('이메일 복사','copy-email','ghost',`data-id="${r.id}"`)}`:''}${btn('연결 청구내역 보기','vendor-requests','secondary',`data-id="${r.id}"`)}</div>`;
 }else if(kind==='approval'){body=`${badge(d.trade,d.trade==='소방'?'fire':'mechanical')}<h2>${e(d.name)}</h2><p>승인목록 버전 ${d.revision||1}${d.effectiveDate?' · 적용일 '+e(d.effectiveDate):''}</p><dl class="detail-grid">${d.options.map(o=>`<dt>제조사 ${e(o.slot)}</dt><dd>${e(vendorName(o.vendorId)||o.name)}</dd>`).join('')}<dt>비고</dt><dd>${e(d.note||'—')}</dd></dl><div class="source">원본: ${e(d.source?.file||'직접 등록')} / ${e(d.source?.sheet||'')} / ${d.source?.row||'—'}행</div>${d.attachmentId?btn('증빙파일 다운로드','file-download','secondary',`data-id="${e(d.attachmentId)}"`):''}`;}
 if(kind==='vendor'&&d.contacts?.length)body+=`<div class="source"><h3>추가 담당자</h3>${d.contacts.map(c=>`<div class="file-row"><div><b>${e(c.name||'담당자')}</b><p>${e(c.phone||'전화 미등록')}<br>${e(c.email||'이메일 미등록')}</p></div>${c.phone?`<a class="btn secondary" href="tel:${e(c.phone.replace(/[^+\d]/g,''))}">전화</a>`:''}${c.email?`<a class="btn secondary" href="mailto:${e(c.email)}">메일</a>`:''}</div>`).join('')}</div>`;
 showDialog(`<div class="modal-body">${body}<div class="dialog-actions">${canEdit()?btn(icon('edit')+' 수정','edit','primary',`data-id="${id}"`):''}${btn(icon('history')+' 변경 이력','item-history','secondary',`data-id="${id}"`)}</div></div>`);
}
function input(name,title,value,type='text',required=false){return `<label>${title}<input type="${type}" name="${name}" value="${e(value??'')}" ${required?'required':''} ${type==='number'?'step="any" min="0"':''}></label>`;}
let contactEditing=null;
