let receiptDraft=null;
function receiptPanel(r){
 const d=r.data,s=receiptSummary(d),events=d.receipts||[];
 return `<section class="receipt-panel"><h3>입고 확인 · ${s.status}</h3><p>입고 ${number(s.received)} / 청구 ${number(d.quantity)} ${e(d.unit)} · 미입고 ${number(s.remaining)} ${e(d.unit)}</p>${canEdit()&&s.remaining>0?btn('입고확인','receipt-open','primary',`data-id="${r.id}"`):''}${s.remaining===null?'<p>청구수량을 양수로 확인한 뒤 입고 처리할 수 있습니다.</p>':''}${events.length?`<details class="receipt-history"><summary>입고·취소 이력 ${events.length}건</summary>${[...events].reverse().map(x=>{const original=x.type==='cancel'?events.find(y=>y.id===x.receiptId):x;return `<div class="receipt-event"><div><b>${x.type==='cancel'?'입고 취소':'입고'} ${number(original?.quantity)} ${e(d.unit)}</b><p>${e(x.actor)} · ${e(stamp(x.at))}${x.reason?'<br>취소 사유: '+e(x.reason):''}</p></div>${canEdit()&&x.type==='receive'&&s.active.some(y=>y.id===x.id)?btn('입고 취소','receipt-cancel','secondary',`data-id="${r.id}" data-receipt="${x.id}"`):''}</div>`;}).join('')}</details>`:''}</section>`;
}
function receiptForm(id,receiptId=''){
 if(!canEdit())throw Error('조회 권한으로는 변경할 수 없습니다.');
 const r=store.records.find(x=>x.id===id&&!x.deleted&&x.kind==='request');if(!r)throw Error('청구내역을 찾을 수 없습니다.');
 const s=receiptSummary(r.data);receiptDraft={id,version:r.version,receiptId};
 showDialog(`<div class="modal-body"><h2>${receiptId?'입고 취소':'입고확인'}</h2><p>${e(r.data.name)} · ${e(r.data.spec)}<br>작업위치: ${e(r.data.location||'미등록')}</p><p>청구 ${number(r.data.quantity)} · 누적 입고 ${number(s.received)} · 미입고 ${number(s.remaining)} ${e(r.data.unit)}</p><form id="receipt-form">${receiptId?'<label>취소 사유<input name="reason" required maxlength="500" placeholder="예: 다른 자재를 잘못 입고 처리함"></label>':`<label>이번 입고수량 (${e(r.data.unit)})<input name="quantity" type="number" required min="0.00001" max="${s.remaining}" step="0.00001" value="${s.remaining}"></label>`}<p>다음 화면에서 내용을 확인한 뒤 확정해야 저장됩니다.</p><div class="dialog-actions">${btn('돌아가기','receipt-back','secondary',`data-id="${id}"`)}<button class="btn primary" type="submit">내용 확인</button></div></form></div>`);
 document.querySelector('#receipt-form').addEventListener('input',event=>event.currentTarget.dataset.dirty='yes');
}
function previewReceipt(form){
 const draft=receiptDraft,r=store.records.find(x=>x.id===draft.id),fd=new FormData(form),actor=store.mode==='cloud'?(store.session?.user?.email||store.session?.user?.id):'로컬 사용자';
 if(!r||r.version!==draft.version)throw Error('다른 화면에서 수정되었습니다. 상세화면을 다시 열어 주세요.');
 const args={actor,quantity:fd.get('quantity'),receiptId:draft.receiptId,reason:fd.get('reason')};
 const next=draft.receiptId?cancelReceipt(r.data,args):addReceipt(r.data,args);
 receiptDraft={...draft,next,reason:draft.receiptId?String(fd.get('reason')).trim():'실물 수량 확인 후 입고 확정'};
 const event=next.receipts.at(-1),quantity=draft.receiptId?r.data.receipts.find(x=>x.id===draft.receiptId).quantity:event.quantity;
 showDialog(`<div class="modal-body"><h2>${draft.receiptId?'입고 취소 확인':'입고 내용 최종 확인'}</h2><h3>${e(r.data.name)}</h3><p>규격: ${e(r.data.spec||'미등록')}<br>작업위치: ${e(r.data.location||'미등록')}</p><dl class="detail-grid"><dt>청구수량</dt><dd>${number(r.data.quantity)} ${e(r.data.unit)}</dd><dt>${draft.receiptId?'취소수량':'이번 입고'}</dt><dd><strong>${number(quantity)} ${e(r.data.unit)}</strong></dd><dt>처리 후 입고</dt><dd>${number(receiptSummary(next).received)} ${e(r.data.unit)}</dd><dt>확인자</dt><dd>${e(actor)}</dd>${draft.receiptId?'<dt>취소 사유</dt><dd>'+e(receiptDraft.reason)+'</dd>':''}</dl><p>아래 확정 버튼을 눌러야 저장됩니다.</p><div class="dialog-actions">${btn('돌아가기','receipt-back','secondary',`data-id="${r.id}"`)}${btn(draft.receiptId?'입고 취소 확정':'입고 확정','receipt-commit')}</div></div>`);
}
async function commitReceipt(){
 if(!canEdit()||!receiptDraft?.next)throw Error('입고 내용을 다시 확인하세요.');
 const draft=receiptDraft,event=draft.next.receipts.at(-1);event.at=new Date().toISOString();
 await store.save('request',draft.id,draft.next,draft.version,draft.reason,draft.receiptId?'입고 취소':'입고 확인');
 receiptDraft=null;render();detail(draft.id);toast(draft.receiptId?'입고를 취소했습니다. 이력은 보관됩니다.':'입고 확인을 저장했습니다.');
}


const aggregateQuantity=g=>g.count===g.missing?'미확인':number(g.total);
function materialTotalMarkup(d){const g=materialTotal(store.records,d);if(!g)return '';const r=g.rows[0];return `<dt>누적 총청구수량</dt><dd class="material-total"><strong>${aggregateQuantity(g)} ${e(g.unit)}</strong><small>전체 기간 · 동일 품명·규격·단위 · 기계·소방 합산<br>청구 항목 ${number(g.count)}건${g.missing?` · 수량 미확인 ${g.missing}건 제외`:''}${g.adjustment?` · 조정 수량 ${number(g.adjustment)} 포함`:''}<br>실제 입고량은 아래 입고 현황에서 확인하세요.</small>${btn('전체 청구 이력 보기','material-history','secondary',`data-id="${e(r.id)}"`)}</dd>`;}
function aggregateView(){const groups=aggregateMaterials(store.records,aggregateFilter);const selected=groups.filter(g=>aggregateSelection.has(g.key)).length;return title('자재별 집계','자재별로 지금까지 청구한 수량과 청구 이력을 확인하세요.',btn(icon('download')+' 엑셀 내려받기','aggregate-export','secondary'))+`<section class="panel filter-panel"><form id="aggregate-filter" class="aggregate-filter"><label>자재 검색<input name="q" value="${e(aggregateFilter.q)}" placeholder="품명 + 규격 검색 (예: 고무발포 25T)"></label><label>분류<select name="trade">${[['','전체'],['기계','기계'],['소방','소방']].map(([v,n])=>option(v,n,aggregateFilter.trade)).join('')}</select></label><label>시작일<input type="date" name="start" value="${e(aggregateFilter.start)}"></label><label>종료일<input type="date" name="end" value="${e(aggregateFilter.end)}"></label><button class="btn primary" type="submit">조회</button>${btn('초기화','aggregate-reset','secondary')}<label class="aggregate-sort">정렬<select name="sort">${[['name','자재명순'],['latest','최근 청구순'],['count','청구 항목 많은순']].map(([v,n])=>option(v,n,aggregateFilter.sort)).join('')}</select></label></form></section><p class="aggregate-intro">품명·규격·단위가 같은 항목끼리 합산합니다. 기간을 지정하면 해당 기간의 합계가 표시됩니다. 서로 다른 단위는 합산하지 않으며, 수량 미확인 항목은 합계에서 제외합니다.</p><div class="section-heading"><div><h2>자재별 합계 <span class="count">${number(groups.length)}</span></h2><p>체크 후 선택 내역 보기를 누르면 여러 품명의 청구내역을 함께 볼 수 있습니다. 검색조건 변경 시 선택은 해제됩니다.</p></div></div><div class="aggregate-selection"><b>선택 ${selected}개</b>${btn("선택 내역 보기","aggregate-selected","primary",selected?"":"disabled")}${btn("선택 해제","aggregate-clear","secondary",selected?"":"disabled")}</div>${groups.length?`<div class="table-panel"><table class="aggregate-table"><thead><tr><th class="aggregate-check-cell"><input class="aggregate-check" type="checkbox" data-all="true" aria-label="검색 결과 전체 선택" ${groups.length&&selected===groups.length?"checked":""}></th><th>품명 / 규격</th><th>단위</th><th>총청구수량</th><th>기계</th><th>소방</th><th>청구 항목</th><th>미확인</th><th>최근 청구일</th></tr></thead><tbody>${groups.map(g=>`<tr tabindex="0" role="button" data-action="aggregate-detail" data-key="${e(g.key)}" aria-label="${e(g.name+' '+g.spec)} 청구 이력"><td class="aggregate-check-cell"><input type="checkbox" class="aggregate-check" data-key="${e(g.key)}" aria-label="${e(g.name+" "+g.spec)} 선택" ${aggregateSelection.has(g.key)?"checked":""}></td><td><b>${e(g.name)}</b><small>${e(g.spec||'규격 미등록')}</small></td><td>${e(g.unit||'단위 미등록')}</td><td class="agg-quantity">${aggregateQuantity(g)}</td><td>${number(g.mechanical)}</td><td>${number(g.fire)}</td><td>${number(g.count)}건</td><td>${g.missing?g.missing+'건':'—'}</td><td>${e(g.lastDate)}</td></tr>`).join('')}</tbody></table></div>`:empty('집계할 자재가 없습니다.')}`;}
function aggregateDetail(key){const g=aggregateMaterials(store.records,aggregateFilter).find(g=>g.key===key);if(!g)return;showDialog(`<div class="modal-body"><h2>${e(g.name)}</h2><p>${e(g.spec||'규격 미등록')} · ${e(g.unit||'단위 미등록')}</p><div class="material-total"><strong>${aggregateQuantity(g)} ${e(g.unit)}</strong><small>${aggregateFilter.start||aggregateFilter.end?'선택 기간':'전체 기간'} · ${e(aggregateFilter.trade||'기계·소방')} · 청구 항목 ${g.count}건${g.missing?` · 수량 미확인 ${g.missing}건 제외`:''}</small></div><div class="aggregate-summary"><span>양수 청구 ${number(g.positive)}</span><span>음수 조정 ${number(g.adjustment)}</span><span>최초 ${e(g.firstDate)}</span><span>최근 ${e(g.lastDate)}</span></div><div class="table-panel"><table class="aggregate-history"><thead><tr><th>날짜 / 분류</th><th>청구수량</th><th>작업위치</th><th>신청자</th><th>대리점</th></tr></thead><tbody>${g.rows.map(r=>`<tr tabindex="0" role="button" data-action="detail" data-id="${e(r.id)}"><td>${e(r.data.date)}<small>${e(r.data.trade)}</small></td><td>${number(r.data.quantity)} ${e(g.unit)}</td><td>${e(r.data.location||'—')}</td><td>${e(r.data.applicant||'—')}</td><td>${e(vendorName(r.data.dealerId)||r.data.rawDealer||'—')}</td></tr>`).join('')}</tbody></table></div><p>청구 행을 선택하면 상세정보와 전체 기간 누적수량을 확인할 수 있습니다.</p></div>`,true);}



function aggregateSelectedDetail(){
 const {groups,rows,totals}=selectedMaterialHistory(store.records,aggregateSelection,aggregateFilter);
 if(!rows.length){toast('함께 볼 자재를 먼저 선택하세요.');return;}
 showDialog(`<div class="modal-body"><h2>선택 자재 청구내역</h2><p>${groups.length}개 자재 · 청구 항목 ${rows.length}건 · ${e(aggregateFilter.trade||'기계·소방')} · ${e(aggregateFilter.start||'전체 기간')} ${aggregateFilter.end?'~ '+e(aggregateFilter.end):''}</p><p>${groups.map(g=>e(g.name+' / '+(g.spec||'규격 미등록'))).join(' · ')}</p><div class="material-total">${totals.map(g=>`<p><b>${e(g.spec||'규격 미등록')}</b> · <strong>${aggregateQuantity(g)} ${e(g.unit||'단위 미등록')}</strong><small>기계 ${number(g.mechanical)} · 소방 ${number(g.fire)} · 청구 ${g.count}건${g.missing?' · 수량 미확인 '+g.missing+'건 제외':''}${g.adjustment?' · 음수 조정 '+number(g.adjustment)+' 포함':''}</small></p>`).join('')}</div><p>선택한 품명의 내역을 모아 표시합니다. 원본 품명은 유지하며 규격·단위별로 합계를 나눕니다.</p><div class="table-panel"><table class="aggregate-history"><thead><tr><th>날짜 / 분류</th><th>원래 품명 / 규격</th><th>청구수량</th><th>작업위치</th><th>신청자</th><th>대리점</th></tr></thead><tbody>${rows.map(r=>`<tr tabindex="0" role="button" data-action="detail" data-id="${e(r.id)}"><td>${e(r.data.date)}<small>${e(r.data.trade)}</small></td><td><b>${e(r.data.name)}</b><small>${e(r.data.spec||'규격 미등록')}</small></td><td>${number(r.data.quantity)} ${e(r.data.unit)}</td><td>${e(r.data.location||'—')}</td><td>${e(r.data.applicant||'—')}</td><td>${e(vendorName(r.data.dealerId)||r.data.rawDealer||'—')}</td></tr>`).join('')}</tbody></table></div></div>`,true);
}
